def solution() -> tuple[list[int], int]:
    import heapq
    # Define graph as adjacency list
    graph = {
        0: {1: 2},
        1: {3: 7, 4: 7},
        2: {0: 1, 1: 3},
        3: {0: 2},
        4: {}
    }

    # Dijkstra's algorithm
    n = 5  # Nodes 0-4
    dist = [float('inf')] * n
    prev = [-1] * n  # To reconstruct path
    dist[0] = 0

    # Priority queue: (distance, node)
    pq = [(0, 0)]

    while pq:
        d, u = heapq.heappop(pq)
        if d != dist[u]:
            continue
        for v, weight in graph[u].items():
            alt = d + weight
            if alt < dist[v]:
                dist[v] = alt
                prev[v] = u
                heapq.heappush(pq, (alt, v))

    # Reconstruct path from 0 to 4
    path = []
    u = 4
    if dist[4] != float('inf'):
        while u != -1:
            path.insert(0, u)
            u = prev[u]

    total_distance = dist[4] if dist[4] != float('inf') else -1
    return path, int(total_distance)

