def solution() -> dict:
    from pulp import LpProblem, LpMinimize, LpVariable, lpSum, LpStatusOptimal, value

    model = LpProblem("Graph_Coloring", LpMinimize)

    vertices = [1, 2, 3, 4, 5, 6]
    colors = ['A', 'B', 'C']

    # Create binary variables for each vertex and color
    color_vars = LpVariable.dicts('color', [(v, c) for v in vertices for c in colors], cat='Binary')

    # Dummy objective function
    model += 0

    # Each vertex must have exactly one color
    for v in vertices:
        model += lpSum([color_vars[v, c] for c in colors]) == 1

    # Add constraints for adjacent vertices
    edges = [(1, 3), (1, 5), (1, 6), (2, 5), (4, 5), (4, 6), (5, 6)]
    for u, v in edges:
        for c in colors:
            model += color_vars[u, c] + color_vars[v, c] <= 1

    # Solve the problem
    model.solve()

    # Extract the solution
    color_assignment = {}
    if LpStatusOptimal == model.status:
        for v in vertices:
            for c in colors:
                if value(color_vars[v, c]) == 1:
                    color_assignment[v] = c
    else:
        raise Exception("No feasible solution found")

    return color_assignment

